function layoutIslands(names){const tops=names.filter(N=>!N.parent);const out=tops.map((N,i)=>{if(i===0)return{id:N.id,c:N.c,e:N.e,col:N.col,sz:N.sz||1,x:0,z:0,terr:!!N.terr,up:N.up||0,dn:N.dn||0,h:N.h||0};const a=-Math.PI/2+(i-1)/(tops.length-1)*Math.PI*2;return{id:N.id,c:N.c,e:N.e,col:N.col,sz:N.sz||1,x:Math.round(Math.cos(a)*20),z:Math.round(Math.sin(a)*20),terr:!!N.terr,up:N.up||0,dn:N.dn||0,h:N.h||0};});const byP={};names.filter(N=>N.parent).forEach(N=>{(byP[N.parent]=byP[N.parent]||[]).push(N);});Object.keys(byP).forEach(pid=>{const P=out.find(o=>o.id===pid);const ks=byP[pid];if(!P){ks.forEach((N,i)=>{const a=-Math.PI/2+i/Math.max(1,ks.length)*Math.PI*2;out.push({id:N.id,c:N.c,e:N.e,col:N.col||PALETTE[out.length%PALETTE.length],sz:N.sz||1,x:Math.round(Math.cos(a)*20),z:Math.round(Math.sin(a)*20),terr:!!N.terr,up:N.up||0,dn:N.dn||0,h:N.h||0});});return;}ks.forEach((N,k)=>{const a=k/Math.max(1,ks.length)*Math.PI*2;out.push({id:N.id,c:N.c,e:N.e,col:N.col||PALETTE[out.length%PALETTE.length],parent:pid,sz:N.sz||1,x:P.x+Math.round(Math.cos(a)*13),z:P.z+Math.round(Math.sin(a)*13),terr:!!N.terr,up:N.up||0,dn:N.dn||0,h:N.h||0});});});out.forEach(o=>{const s=names.find(N=>N.id===o.id);if(s&&s.px!==undefined){o.x=Math.max(-60,Math.min(60,+s.px));o.z=Math.max(-60,Math.min(60,+s.pz));}});return out;}
