function buildFurn(k){const d=furnDef().find(f=>f.k===k);const g=new THREE.Group();(d.parts||[]).forEach(p=>{let m;const mt=new THREE.MeshLambertMaterial({color:p.c});if(p.t==='b')m=new THREE.Mesh(new THREE.BoxGeometry(p.a[0],p.a[1],p.a[2]),mt);else if(p.t==='c')m=new THREE.Mesh(new THREE.CylinderGeometry(p.a[0],p.a[1],p.a[2],p.a[3]||10),mt);else if(p.t==='n')m=new THREE.Mesh(new THREE.ConeGeometry(p.a[0],p.a[1],p.a[2]||10),mt);else m=new THREE.Mesh(new THREE.SphereGeometry(p.a[0],p.a[1]||10,p.a[2]||8),mt);m.position.set(p.p[0],p.p[1],p.p[2]);if(p.r)m.rotation.set(p.r[0],p.r[1],p.r[2]);g.add(m);});return g;}
