function syncG(isl){const gg=groups[isl.id];if(gg){gg.position.x=isl.x;gg.position.z=isl.z;}}
function moveGroup(isl,nx,nz){nx=Math.round(nx);nz=Math.round(nz);const _dx=nx-isl.x,_dz=nz-isl.z;moveIsland(isl,nx,nz);syncG(isl);if(!_dx&&!_dz)return;{const desc=new Set([isl.id]);let more=true;while(more){more=false;ISLANDS.forEach(k=>{if(k.parent&&desc.has(k.parent)&&!desc.has(k.id)){desc.add(k.id);moveIsland(k,k.x+_dx,k.z+_dz);syncG(k);saveIslandPos(k);more=true;}});}}saveIslandPos(isl);}
function moveIsland(isl,nx,nz){nx=Math.max(-60,Math.min(60,+nx));nz=Math.max(-60,Math.min(60,+nz));const dx=nx-isl.x,dz=nz-isl.z;if(Math.abs(dx)<1e-9&&Math.abs(dz)<1e-9)return;isl.x=nx;isl.z=nz;(islExtra[isl.id]||[]).forEach(m=>{m.position.x+=dx;m.position.z+=dz;});FLOORD.forEach(o=>{if(o.isl===isl.id){o.x+=dx;o.z+=dz;}});FLOORS_.forEach(o=>{if(o.isl===isl.id){o.ax+=dx;o.az+=dz;o.bx+=dx;o.bz+=dz;}});FLOORPEND.forEach(f=>{if(f.isl===isl.id){f.sx+=dx;f.sz_+=dz;f.fx+=dx;f.fz+=dz;if(NODES[f.S]){NODES[f.S][0]+=dx;NODES[f.S][1]+=dz;}if(NODES[f.F]){NODES[f.F][0]+=dx;NODES[f.F][1]+=dz;}}});Object.keys(shelfStand).forEach(f=>{const m=shelfMap[f];if(((m&&m.i)||m)===isl.id&&shelfStand[f]){shelfStand[f][0]+=dx;shelfStand[f][1]+=dz;}});{const ci=ISLANDS.findIndex(o=>o.id===isl.id);if(ci>=0)NODES['I'+ci]=[isl.x,isl.z];const fixM=j=>{const J=ISLANDS[j];if(!J||!NODES['M'+j])return;const PP=J.parent?ISLANDS.find(o=>o.id===J.parent):ISLANDS[0];const ax=PP?PP.x:0,az=PP?PP.z:0;NODES['M'+j]=[(ax+J.x)/2,(az+J.z)/2];};if(ci===0){ISLANDS.forEach((J,j)=>{if(j>0&&!J.parent)fixM(j);});}else if(ci>0)fixM(ci);}refreshSpokes();}
function refreshSpokes(){spokeMeshes.forEach(b=>{try{if(b.parent)b.parent.remove(b);}catch(e){}});spokeMeshes.length=0;SPOKES.length=0;const RR=I=>(I.small?4.6:8*(I.sz||1));ISLANDS.forEach((I,i)=>{if(I.parent){const P=ISLANDS.find(o=>o.id===I.parent);if(P)SPOKES.push([P.x,P.z,I.x,I.z,P.id,I.id]);}else if(i>0)SPOKES.push([ISLANDS[0].x,ISLANDS[0].z,I.x,I.z,ISLANDS[0].id,I.id]);});SPOKES.forEach(sg=>{const x1=sg[0],z1=sg[1],x2=sg[2],z2=sg[3];const A=ISLANDS.find(o=>o.id===sg[4]),B=ISLANDS.find(o=>o.id===sg[5]);const dx=x2-x1,dz=z2-z1,D=Math.hypot(dx,dz)||1,ux=dx/D,uz=dz/D;const a=A?RR(A)-.5:2,b=D-(B?RR(B)-.5:2);if(b-a<1.5)return;const h1=A?A.h||0:0,h2=B?B.h||0:0,len=b-a,len3=Math.hypot(len,h2-h1),bdg=new THREE.Mesh(new THREE.BoxGeometry(2.2,.5,len3),new THREE.MeshLambertMaterial({color:0xc08a4e}));bdg.position.set(x1+ux*(a+b)/2,(h1+h2)/2+.35,z1+uz*(a+b)/2);bdg.rotation.order='YXZ';bdg.rotation.y=Math.atan2(ux,uz);bdg.rotation.x=-Math.atan2(h2-h1,len);WORLD.add(bdg);spokeMeshes.push(bdg);});}
