{const gal=(Array.isArray(n.pics)&&n.pics.length?n.pics:(n.pic?[n.pic]:[]));if(gal.length){const cw=document.createElement('div');cw.innerHTML='<img id=\u0022gMain\u0022 src=\u0022'+gal[0]+'\u0022 style=\u0022width:100%;border-radius:8px;margin-top:8px\u0022>'+(gal.length>1?'<div style=\u0022display:flex;gap:4px;margin-top:4px;flex-wrap:wrap\u0022>'+gal.map((s,i)=>'<img data-gi=\u0022'+i+'\u0022 src=\u0022'+s+'\u0022 style=\u0022width:52px;height:52px;object-fit:cover;border-radius:6px;cursor:pointer;'+(i?'opacity:.7':'')+'\u0022>').join('')+'</div>':'');document.getElementById('rm').appendChild(cw);cw.querySelectorAll('[data-gi]').forEach(el=>el.onclick=()=>{document.getElementById('gMain').src=gal[+el.getAttribute('data-gi')];});}}
