function speak(t){try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.rate=.95;const vs=speechSynthesis.getVoices();const v=vs.find(v=>/xiaoxiao|mei-jia|yunjian|hongkong|hk-|yue|guangdong|cantonese/i.test(v.name+' '+v.lang))||vs.find(v=>/^zh/i.test(v.lang));if(v){u.voice=v;u.lang=v.lang;}else u.lang='zh-HK';speechSynthesis.speak(u);}catch(e){}}
