  if(!(isStair&&(Math.abs(ny(sn)-P.position.y)>2.5||Math.abs(ny(sn)-ey)>2.5)))return[new THREE.Vector3(fx,.7,fz)];
  const sKey=(LINKS[sn]||[]).find(n=>n[0]==='S')||sn;
