let lastT=performance.now();
let WX={mode:'sunny'};{const ms=['sunny','cloudy','rainy','storm','typhoon','rainbow','mist','starry','sunset','petals','night'];WX.mode=(Math.random()<.06?'meteor':ms[Math.floor(Math.random()*ms.length)]);try{localStorage.setItem('island_wx',JSON.stringify(WX));}catch(e){}}
const WXN={sunny:'\u6674',cloudy:'\u9670',rainy:'\u96E8',storm:'\u66B4\u96E8',typhoon:'\u98B1\u98A8',rainbow:'\u5F69\u8679',mist:'\u8584\u9727',starry:'\u661F\u591C',meteor:'\u6D41\u661F\u591C',sunset:'\u9EC3\u660F',petals:'\u82B1\u74E3\u96E8',night:'\u591C'};
let rainPts=null;let WINDX=0,WSPD=26;
function setRain(on){if(on&&!rainPts){const N=700,pos=new Float32Array(N*3);for(let i=0;i<N;i++){pos[i*3]=(Math.random()-.5)*70;pos[i*3+1]=Math.random()*22;pos[i*3+2]=(Math.random()-.5)*70;}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(pos,3));rainPts=new THREE.Points(g,new THREE.PointsMaterial({color:0xbfe0ff,size:.18,transparent:true,opacity:.85}));WORLD.add(rainPts);}if(rainPts)rainPts.visible=!!on;}
function updateRain(dt){if(!rainPts||!rainPts.visible)return;const pp=rainPts.geometry.attributes.position;for(let i=0;i<pp.count;i++){let y=pp.getY(i)-WSPD*dt;if(y<0)y=22;pp.setY(i,y);if(WINDX||WX.sway){let x=pp.getX(i)+WINDX*dt+(WX.sway?Math.sin(performance.now()/350+i*1.3)*dt*4:0);if(x>35)x=-35;if(x<-35)x=35;pp.setX(i,x);}}pp.needsUpdate=true;}
let rainbow=null;function setRainbow(on){if(on&&!rainbow){rainbow=new THREE.Group();[0xff5b5b,0xffa94d,0xffd93d,0x6fce8f,0x7fb8f2].forEach((c,i)=>{rainbow.add(new THREE.Mesh(new THREE.TorusGeometry(15-i*1.1,.45,8,32,Math.PI),new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:.75,side:THREE.DoubleSide})));});rainbow.position.set(0,1,-28);WORLD.add(rainbow);}if(rainbow)rainbow.visible=!!on;}
function updateWind(){const w=WX.wind||0;if(!swayTrees.length)return;const tt=performance.now()/300;for(let i=0;i<swayTrees.length;i++)swayTrees[i].rotation.z=Math.sin(tt+i*1.7)*w*.12;}
function lightning(){if(!WX.flash)return;if(Math.random()<.008){hemi.intensity=5;sun.intensity=2;setTimeout(applyWeather,130);}}
let stars=null;function setStars(on){if(on&&!stars){const N=450,pos=new Float32Array(N*3);for(let i=0;i<N;i++){const a=Math.random()*Math.PI*2,e=Math.random()*1.2+.08,r=140;pos[i*3]=Math.cos(a)*Math.cos(e)*r;pos[i*3+1]=Math.sin(e)*r;pos[i*3+2]=Math.sin(a)*Math.cos(e)*r;}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(pos,3));stars=new THREE.Points(g,new THREE.PointsMaterial({color:0xffffff,size:1.6,sizeAttenuation:false,transparent:true,opacity:.9}));WORLD.add(stars);}if(stars)stars.visible=!!on;}
const RADIANT={x:40,y:50,z:-30};
function canvasTex(w,h,fn){const c=document.createElement('canvas');c.width=w;c.height=h;fn(c.getContext('2d'),w,h);return new THREE.CanvasTexture(c);}
const dotTex=canvasTex(64,64,(g)=>{const r=g.createRadialGradient(32,32,0,32,32,32);r.addColorStop(0,'rgba(255,255,255,1)');r.addColorStop(.35,'rgba(255,255,255,.8)');r.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=r;g.fillRect(0,0,64,64);});
const trailGeo=[2.2,2.4,2.8].map((L,i)=>{const g=new THREE.BoxGeometry(L,.34-i*.08,.34-i*.08);g.translate(-L/2-(i===0?0:(i===1?2.2:4.6)),0,0);return g;});
const trailBase=[.85,.45,.18];
let shoots=[];function meteors(dt){if(stars)stars.material.opacity=.65+.3*Math.abs(Math.sin(performance.now()/700));if(WX.mode!=='meteor'){for(const s of shoots){WORLD.remove(s.m);s.hm.dispose();for(let k=0;k<3;k++){s.mats[k].dispose();}}shoots=[];return;}if(shoots.length<24&&Math.random()<dt*8){const g=new THREE.Group();const px=(Math.random()-.5)*120,py=20+Math.random()*25,pz=(Math.random()-.5)*120;let vx=px-RADIANT.x,vy=py-RADIANT.y,vz=pz-RADIANT.z;const vl=Math.hypot(vx,vy,vz)||1,sp=26+Math.random()*10;vx=vx/vl*sp;vy=vy/vl*sp;vz=vz/vl*sp;g.position.set(px,py,pz);g.lookAt(px+vx,py+vy,pz+vz);g.rotateY(-Math.PI/2);const mats=trailBase.map(o=>new THREE.MeshBasicMaterial({color:0xcfe6ff,transparent:true,opacity:o,blending:THREE.AdditiveBlending,depthWrite:false}));for(let k=0;k<3;k++){g.add(new THREE.Mesh(trailGeo[k],mats[k]));}const hm=new THREE.SpriteMaterial({map:dotTex,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false});const head=new THREE.Sprite(hm);head.scale.set(1.6,1.6,1);g.add(head);WORLD.add(g);shoots.push({m:g,hm:hm,head:head,mats:mats,vx:vx,vy:vy,vz:vz,life:3.2,seed:Math.random()*10});}for(let i=shoots.length-1;i>=0;i--){const sh=shoots[i];sh.m.position.x+=sh.vx*dt;sh.m.position.y+=sh.vy*dt;sh.m.position.z+=sh.vz*dt;sh.life-=dt;const age=3.2-sh.life;const fade=Math.min(1,age/.25)*Math.min(1,Math.max(0,sh.life)/1.2);const fl=.75+.25*Math.sin(performance.now()/60+sh.seed*7);sh.hm.opacity=fade*fl;const hs=1.2+.6*fl*fade;sh.head.scale.set(hs,hs,1);for(let k=0;k<3;k++){sh.mats[k].opacity=trailBase[k]*fade;}if(sh.life<=0){WORLD.remove(sh.m);sh.hm.dispose();for(let k=0;k<3;k++){sh.mats[k].dispose();}shoots.splice(i,1);}}}
function applyWeather(){const m=WX.mode||'sunny';const wn=document.getElementById('wxNow');if(wn)wn.textContent='\u5929\u6C23\uFF1A'+(WXN[m]||m);const C={sunny:[0x8ecfee,1.1,.9,0x2f9fd8,0,.15,0],cloudy:[0x9db3c8,.8,.4,0x5b8fb0,0,.12,0],rainy:[0x7c8ea0,.6,.25,0x4a6f85,1,.3,0],storm:[0x5a6a7d,.45,.2,0x3a5a75,2,.55,1],typhoon:[0x4a4a55,.35,.15,0x2f4a60,2,1,1],rainbow:[0x9fd4e8,1.15,.95,0x2f9fd8,0,.15,0],mist:[0xccd6d6,.65,.45,0x7fa0ac,0,.08,0],starry:[0x0a1428,.22,.05,0x16283f,0,.05,0],meteor:[0x0d1029,.22,.05,0x16283f,0,.05,0],sunset:[0xef9a5e,.75,.8,0xb0766a,0,.12,0],petals:[0xbfe0dd,1,.8,0x2f9fd8,1,.2,0],night:[0x0b1622,.3,.12,0x1d3350,0,.05,0]}[m]||[0x8ecfee,1.1,.9,0x2f9fd8,0,.15,0];scene.background.set(C[0]);scene.fog.color.set(C[0]);scene.fog.near=EXT*(m==='mist'?1.2:2);scene.fog.far=EXT*(m==='mist'?3.5:5);hemi.intensity=C[1];sun.intensity=C[2];sun.color.set({night:0x9db3ff,starry:0x9db3ff,meteor:0x9db3ff,sunset:0xff9a4d}[m]||0xffffff);if(m==='sunset')sun.position.set(25,7,8);else sun.position.set(20,30,10);setStars(m==='night'||m==='starry'||m==='meteor');sea.material.color.set(C[3]);setRain(C[4]>0);WSPD=C[4]===2?44:(m==='petals'?9:26);WINDX=C[4]===2?9:(C[4]===1?2:0);WX.wind=C[5];WX.flash=C[6];WX.sway=(m==='petals');setRainbow(m==='rainbow');if(rainPts){rainPts.material.color.set({rainy:0xbfe0ff,storm:0xbfe0ff,typhoon:0xaed4e6,petals:0xffb7c9}[m]||0xbfe0ff);rainPts.material.size=(m==='petals'?.3:(C[4]===2?.22:.18));}}
let wxT=null;function wxAuto(){if(wxT)clearInterval(wxT);wxT=setInterval(()=>{const ms=['sunny','cloudy','rainy','storm','typhoon','rainbow','mist','night'];if(Math.random()<.06)setWeather('meteor');else setWeather(ms[Math.floor(Math.random()*ms.length)]);},600000);}
